compliant:
import { Effect } from "effect"

export interface UploadRequest {
  readonly filename: string
  readonly size: number
  readonly authenticated: boolean
}

export interface UploadPolicy {
  readonly maxBytes: number
  readonly allowAnonymous: boolean
}

export const validateUpload = (
  request: UploadRequest,
  policy: UploadPolicy
): Effect.Effect<string, Error> =>
  Effect.gen(function*() {
    if (!request.authenticated && !policy.allowAnonymous) {
      return yield* Effect.fail(new Error("Authentication required"))
    }

    let rejection: string | undefined
    if (request.size === 0) {
      rejection = "The upload is empty"
    } else if (request.size > policy.maxBytes) {
      rejection = "Upload exceeds the size limit"
    } else {
      rejection = undefined
    }

    if (rejection !== undefined) {
      return yield* Effect.fail(new Error(rejection))
    }

    const filename = request.filename.trim()
    if (filename.length === 0) {
      return yield* Effect.fail(new Error("A filename is required"))
    }

    return filename
  })
